import React, { useState, useMemo } from 'react';

// --- SVG Icon Components ---
const EditIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-gray-600 hover:text-blue-600">
    <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
    <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
  </svg>
);

const DeleteIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-gray-600 hover:text-red-600">
    <polyline points="3 6 5 6 21 6"></polyline>
    <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
    <line x1="10" y1="11" x2="10" y2="17"></line>
    <line x1="14" y1="11" x2="14" y2="17"></line>
  </svg>
);

const ChevronLeftIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
);

const ChevronRightIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
);


// --- Initial Data ---
const initialSubjects = [
    { "subjectId": "id001", "subjectCode": "EXPL001", "subjectName": "Example 1", "term": "Spring", "subjectCoordinator": "Tom", "version": 1, "date": "2024-11-18", "formatOfDelivery": "Lecture based", "totalSubjectWorkload": "51.5%", "totalWorkloadAllocation": "51.5%", "unallocatedAvailableWorkload": "0%" },
    { "subjectId": "id002", "subjectCode": "EXPL002", "subjectName": "Example 2", "term": "Autumn", "subjectCoordinator": "Usha", "version": 1, "date": "2024-08-25", "formatOfDelivery": "Project based", "totalSubjectWorkload": "51.5%", "totalWorkloadAllocation": "51.5%", "unallocatedAvailableWorkload": "0%" },
    { "subjectId": "id003", "subjectCode": "EXPL003", "subjectName": "Example 3", "term": "1H", "subjectCoordinator": "Victoria", "version": 1, "date": "2024-04-08", "formatOfDelivery": "Lecture based", "totalSubjectWorkload": "51.5%", "totalWorkloadAllocation": "51.5%", "unallocatedAvailableWorkload": "0%" },
    { "subjectId": "id004", "subjectCode": "EXPL004", "subjectName": "Example 4", "term": "2H", "subjectCoordinator": "Fred", "version": 1, "date": "2024-07-21", "formatOfDelivery": "Project based", "totalSubjectWorkload": "51.5%", "totalWorkloadAllocation": "51.5%", "unallocatedAvailableWorkload": "0%" },
    { "subjectId": "id005", "subjectCode": "EXPL005", "subjectName": "Example 5", "term": "Q1", "subjectCoordinator": "Ian", "version": 1, "date": "2024-03-05", "formatOfDelivery": "Lecture based", "totalSubjectWorkload": "51.5%", "totalWorkloadAllocation": "51.5%", "unallocatedAvailableWorkload": "0%" },
    { "subjectId": "id006", "subjectCode": "EXPL006", "subjectName": "Example 6", "term": "Q2", "subjectCoordinator": "Jane", "version": 1, "date": "2024-11-18", "formatOfDelivery": "Lecture based", "totalSubjectWorkload": "51.5%", "totalWorkloadAllocation": "51.5%", "unallocatedAvailableWorkload": "0%" },
];

const formatDate = (dateString) => {
    const date = new Date(dateString);
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = String(date.getFullYear()).slice(-2);
    return `${day}/${month}/${year}`;
};

// --- Main App Component ---
export default function SubjectManagementPage() {
    // --- State Management ---
    const [subjects, setSubjects] = useState(initialSubjects);
    const [isFormModalOpen, setIsFormModalOpen] = useState(false);
    const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
    const [currentSubject, setCurrentSubject] = useState(null);
    const [subjectToDelete, setSubjectToDelete] = useState(null);

    const [currentPage, setCurrentPage] = useState(1);
    const [rowsPerPage, setRowsPerPage] = useState(10);
    const rowsPerPageOptions = [10, 25, 50];

    // --- Memoized Pagination Calculation ---
    const paginatedSubjects = useMemo(() => {
        const startIndex = (currentPage - 1) * rowsPerPage;
        const endIndex = startIndex + rowsPerPage;
        return subjects.slice(startIndex, endIndex);
    }, [subjects, currentPage, rowsPerPage]);

    const totalPages = Math.ceil(subjects.length / rowsPerPage);

    // --- Event Handlers ---
    const handleAddSubject = () => {
        setCurrentSubject({
            subjectCode: '',
            subjectName: '',
            term: 'Spring',
            subjectCoordinator: '',
            version: 1,
            date: new Date().toISOString().split('T')[0],
            formatOfDelivery: 'Lecture based',
        });
        setIsFormModalOpen(true);
    };

    const handleEditSubject = (subject) => {
        setCurrentSubject(subject);
        setIsFormModalOpen(true);
    };

    const handleDeleteSubject = (subject) => {
        setSubjectToDelete(subject);
        setIsDeleteModalOpen(true);
    };

    const handleSaveSubject = (e) => {
        e.preventDefault();
        if (currentSubject.subjectId) {
            // Edit existing subject
            setSubjects(subjects.map(s => s.subjectId === currentSubject.subjectId ? currentSubject : s));
        } else {
            // Add new subject
            const newSubject = {
                ...currentSubject,
                subjectId: `id${Date.now()}`, // Simple unique ID
                totalSubjectWorkload: "0%", // Default values
                totalWorkloadAllocation: "0%",
                unallocatedAvailableWorkload: "0%",
            };
            setSubjects([newSubject, ...subjects]);
        }
        closeFormModal();
    };

    const handleConfirmDelete = () => {
        setSubjects(subjects.filter(s => s.subjectId !== subjectToDelete.subjectId));
        closeDeleteModal();
    };

    const closeFormModal = () => {
        setIsFormModalOpen(false);
        setCurrentSubject(null);
    };

    const closeDeleteModal = () => {
        setIsDeleteModalOpen(false);
        setSubjectToDelete(null);
    };

    const handlePageChange = (newPage) => {
        if (newPage >= 1 && newPage <= totalPages) {
            setCurrentPage(newPage);
        }
    };

    return (
        <div className="bg-gray-50 min-h-screen font-sans text-gray-800 p-4 sm:p-6 lg:p-8">
            <div className="max-w-7xl mx-auto bg-white rounded-xl shadow-md border border-gray-200">
                {/* Header */}
                <div className="p-6 border-b border-gray-200 flex justify-between items-center">
                    <h1 className="text-2xl font-semibold text-gray-900">Subject Workload Management</h1>
                    <button
                        onClick={handleAddSubject}
                        className="px-4 py-2 bg-black text-white rounded-lg font-semibold text-sm hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 transition-colors"
                    >
                        Add Subject
                    </button>
                </div>

                {/* Data Table */}
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-50 text-xs text-gray-600 uppercase tracking-wider border-b border-gray-200">
                            <tr>
                                <th className="px-6 py-3 font-medium">Subject Code</th>
                                <th className="px-6 py-3 font-medium">Subject Name</th>
                                <th className="px-6 py-3 font-medium">Term</th>
                                <th className="px-6 py-3 font-medium">Subject Coordinator</th>
                                <th className="px-6 py-3 font-medium">Version</th>
                                <th className="px-6 py-3 font-medium">Date</th>
                                <th className="px-6 py-3 font-medium">Format of delivery</th>
                                <th className="px-6 py-3 font-medium">Total Subject Workload</th>
                                <th className="px-6 py-3 font-medium">Total Workload Allocation</th>
                                <th className="px-6 py-3 font-medium">Unallocated Workload</th>
                                <th className="px-6 py-3 font-medium text-center">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200">
                            {paginatedSubjects.map((subject) => (
                                <tr key={subject.subjectId} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 whitespace-nowrap font-medium text-gray-900">{subject.subjectCode}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{subject.subjectName}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{subject.term}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{subject.subjectCoordinator}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-center">{subject.version}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{formatDate(subject.date)}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{subject.formatOfDelivery}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{subject.totalSubjectWorkload}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{subject.totalWorkloadAllocation}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">{subject.unallocatedAvailableWorkload}</td>
                                    <td className="px-6 py-4 whitespace-nowrap">
                                        <div className="flex items-center justify-center space-x-4">
                                            <button onClick={() => handleEditSubject(subject)} title="Edit Subject"><EditIcon /></button>
                                            <button onClick={() => handleDeleteSubject(subject)} title="Delete Subject"><DeleteIcon /></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                {/* Pagination Controls */}
                <div className="p-4 border-t border-gray-200 flex items-center justify-between flex-wrap gap-4">
                    <div className="flex items-center gap-2 text-sm">
                        <span className="text-gray-600">Rows per page:</span>
                        <select
                            value={rowsPerPage}
                            onChange={(e) => {
                                setRowsPerPage(Number(e.target.value));
                                setCurrentPage(1);
                            }}
                            className="bg-white border border-gray-300 rounded-md px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                        >
                            {rowsPerPageOptions.map(option => <option key={option} value={option}>{option}</option>)}
                        </select>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                         <span className="text-gray-600">
                            Page {currentPage} of {totalPages}
                        </span>
                        <div className="flex items-center">
                             <button
                                onClick={() => handlePageChange(currentPage - 1)}
                                disabled={currentPage === 1}
                                className="p-1 rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
                            >
                                <ChevronLeftIcon/>
                            </button>
                            <button
                                onClick={() => handlePageChange(currentPage + 1)}
                                disabled={currentPage === totalPages}
                                className="p-1 rounded-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
                            >
                                <ChevronRightIcon/>
                            </button>
                        </div>
                    </div>
                </div>

            </div>

            {/* --- Modals --- */}

            {/* Add/Edit Subject Form Modal */}
            {isFormModalOpen && currentSubject && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-lg shadow-xl w-full max-w-lg">
                        <form onSubmit={handleSaveSubject}>
                            <div className="p-6">
                                <h2 className="text-xl font-semibold text-gray-900">{currentSubject.subjectId ? 'Edit Subject' : 'Add Subject'}</h2>
                                <p className="text-sm text-gray-500 mt-1">Complete all sections that apply to your subject.</p>

                                <div className="mt-6 grid grid-cols-1 sm:grid-cols-2 gap-4">
                                    {/* Form Fields */}
                                    <div>
                                        <label htmlFor="subjectCode" className="block text-sm font-medium text-gray-700">Subject Code</label>
                                        <input type="text" name="subjectCode" id="subjectCode" required value={currentSubject.subjectCode} onChange={(e) => setCurrentSubject({...currentSubject, subjectCode: e.target.value})} className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm" />
                                    </div>
                                    <div>
                                        <label htmlFor="subjectName" className="block text-sm font-medium text-gray-700">Subject Name</label>
                                        <input type="text" name="subjectName" id="subjectName" required value={currentSubject.subjectName} onChange={(e) => setCurrentSubject({...currentSubject, subjectName: e.target.value})} className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm" />
                                    </div>
                                    <div>
                                        <label htmlFor="term" className="block text-sm font-medium text-gray-700">Term</label>
                                        <select id="term" name="term" required value={currentSubject.term} onChange={(e) => setCurrentSubject({...currentSubject, term: e.target.value})} className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm">
                                            {["Spring", "Autumn", "1H", "2H", "Q1", "Q2"].map(opt => <option key={opt}>{opt}</option>)}
                                        </select>
                                    </div>
                                    <div>
                                        <label htmlFor="subjectCoordinator" className="block text-sm font-medium text-gray-700">Subject Coordinator</label>
                                        <input type="text" name="subjectCoordinator" id="subjectCoordinator" required value={currentSubject.subjectCoordinator} onChange={(e) => setCurrentSubject({...currentSubject, subjectCoordinator: e.target.value})} className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm" />
                                    </div>
                                    <div>
                                        <label htmlFor="version" className="block text-sm font-medium text-gray-700">Version</label>
                                        <input type="number" name="version" id="version" required value={currentSubject.version} onChange={(e) => setCurrentSubject({...currentSubject, version: Number(e.target.value)})} className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm" />
                                    </div>
                                    <div>
                                        <label htmlFor="date" className="block text-sm font-medium text-gray-700">Date</label>
                                        <input type="date" name="date" id="date" required value={currentSubject.date} onChange={(e) => setCurrentSubject({...currentSubject, date: e.target.value})} className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm" />
                                    </div>
                                    <div className="sm:col-span-2">
                                        <label htmlFor="formatOfDelivery" className="block text-sm font-medium text-gray-700">Format of delivery</label>
                                        <select id="formatOfDelivery" name="formatOfDelivery" required value={currentSubject.formatOfDelivery} onChange={(e) => setCurrentSubject({...currentSubject, formatOfDelivery: e.target.value})} className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm">
                                            {["Lecture based", "Project based"].map(opt => <option key={opt}>{opt}</option>)}
                                        </select>
                                    </div>
                                </div>
                            </div>
                            <div className="bg-gray-50 px-6 py-3 flex justify-end space-x-3 rounded-b-lg">
                                <button type="button" onClick={closeFormModal} className="px-4 py-2 bg-white text-gray-700 border border-gray-300 rounded-md font-semibold text-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500">
                                    Cancel
                                </button>
                                <button type="submit" className="px-4 py-2 bg-black text-white rounded-md font-semibold text-sm hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900">
                                    Save Subject
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Delete Confirmation Modal */}
            {isDeleteModalOpen && subjectToDelete && (
                 <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-lg shadow-xl w-full max-w-md">
                        <div className="p-6">
                            <h2 className="text-xl font-semibold text-gray-900">Confirm Deletion</h2>
                            <p className="mt-2 text-sm text-gray-600">
                                Are you sure you want to delete the subject "{subjectToDelete.subjectName}"? This action cannot be undone.
                            </p>
                        </div>
                         <div className="bg-gray-50 px-6 py-3 flex justify-end space-x-3 rounded-b-lg">
                            <button onClick={closeDeleteModal} className="px-4 py-2 bg-white text-gray-700 border border-gray-300 rounded-md font-semibold text-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500">
                                Cancel
                            </button>
                            <button onClick={handleConfirmDelete} className="px-4 py-2 bg-red-600 text-white rounded-md font-semibold text-sm hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500">
                                Confirm Delete
                            </button>
                        </div>
                    </div>
                 </div>
            )}
        </div>
    );
}
